const METADATA_FETCH_TIMEOUT_MS = 30_000;
const PAYLOAD_FETCH_TIMEOUT_MS = 15 * 60_000;
const PATCH_APPLY_TIMEOUT_MS = 10 * 60_000;
const MAX_PATCH_BYTES = 512 * 1024 * 1024;
const MAX_BINARY_BYTES = 1024 * 1024 * 1024;
const PATCH_SIZE_SLACK = 1.25;
async function fetchWithTimeout(
	url: string,
	options: { timeoutMs: number; signal?: AbortSignal; transport?: UpdateFetchContext },
): Promise<Response> {
	return fetchUpdateWithTimeout(url, options);
}
async function streamResponseToFile(
	response: Response,
	filePath: string,
	options: { maxBytes: number; onProgress?: (bytesWritten: number) => void },
): Promise<number> {
	const declaredLength = Number(response.headers.get("content-length") ?? 0);
	if (Number.isFinite(declaredLength) && declaredLength > options.maxBytes) {
		throw new Error(
			`Update payload declares ${declaredLength} bytes, over the ${options.maxBytes}-byte limit`,
		);
	}
	if (!response.body) throw new Error("Update payload response had no body");

	const handle = await open(filePath, "w");
	let written = 0;
	try {
		const reader = response.body.getReader();
		try {
			while (true) {
				const { done, value } = await reader.read();
				if (done) break;
				written += value.byteLength;
				if (written > options.maxBytes) {
					throw new Error(`Update payload exceeded the ${options.maxBytes}-byte limit`);
				}
				await handle.write(value);
				options.onProgress?.(written);
			}
		} finally {
			await reader.cancel().catch(() => {});
		}
	} finally {
		await handle.close();
	}
	return written;
}
function safeUnlink(filePath: string): void {
	try {
		if (existsSync(filePath)) unlinkSync(filePath);
	} catch {
		// Best effort cleanup.
	}
}
function sanitizeVersionFragment(version: string): string {
	return version.replace(/[^a-zA-Z0-9._-]+/g, "-") || "unknown";
}
function sanitizeUpdateFileName(filePath: string, version: string): string {
	const fallbackExt = process.platform === "win32" ? ".exe" : "";
	const fallback = `narrafork-${sanitizeVersionFragment(version)}${fallbackExt}`;
	const baseName = basename(filePath).replace(/[<>:"/\\|?*]+/g, "-");
	if (!baseName || baseName === "." || baseName === "..") return fallback;
	return baseName;
}
function resolveSameOriginUrl(serverBase: string, candidate: string): string | null {
	try {
		const base = new URL(serverBase);
		const resolved = new URL(candidate, base);
		if (resolved.origin !== base.origin) {
			logger.warn("Discarded update URL pointing at a different origin", {
				serverOrigin: base.origin,
				resolvedOrigin: resolved.origin,
			});
			return null;
		}
		return resolved.toString();
	} catch (error) {
		logger.warn("Discarded unparseable update URL", {
			error: error instanceof Error ? error.message : String(error),
		});
		return null;
	}
}
function resolveSameOriginPatchUrls(
	serverBase: string,
	step: { url: string; metaUrl: string },
): { url: string; metaUrl: string } | null {
	const url = resolveSameOriginUrl(serverBase, step.url);
	const metaUrl = resolveSameOriginUrl(serverBase, step.metaUrl);
	if (!url || !metaUrl) return null;
	return { url, metaUrl };
}
function resolveSameOriginPatchChain(
	serverBase: string,
	chain: Array<{
		fromVersion: string;
		toVersion: string;
		patchSize: number;
		url: string;
		metaUrl: string;
	}>,
): NonNullable<ReleaseInfo["_v2"]>["patchChain"] {
	const resolved: NonNullable<NonNullable<ReleaseInfo["_v2"]>["patchChain"]> = [];
	for (const step of chain) {
		const urls = resolveSameOriginPatchUrls(serverBase, step);
		if (!urls) return undefined;
		resolved.push({ ...step, ...urls });
	}
	return resolved;
}
async function checkChannel(
	serverUrl: string,
	product: string,
	channel: string,
	platform: string,
	transport: UpdateFetchContext,
): Promise<UpdateCheckResult> {
	const checkUrl = `${serverUrl}/api/v2/products/${product}/releases/latest?channel=${channel}&platform=${platform}&version=${APP_VERSION}`;
	logger.debug("Checking for updates", { url: checkUrl, channel });

	const response = await fetchWithTimeout(checkUrl, {
		timeoutMs: METADATA_FETCH_TIMEOUT_MS,
		transport,
	});
	if (!response.ok) {
		void response.body?.cancel().catch(() => {});
		logger.warn("Update check failed", { status: response.status, channel });
		return {
			updateAvailable: false,
			currentVersion: APP_VERSION,
			errorCode: "NETWORK_ERROR",
			error: `Update server returned HTTP ${response.status}`,
		};
	}

	const data = (await readUpdateJson(response)) as V2CheckResponse;

	if (!data.updateAvailable || !data.version || !data.file) {
		return {
			updateAvailable: false,
			currentVersion: APP_VERSION,
			latestVersion: data.version,
		};
	}

	const directPatchUrls = data.zstdPatch
		? resolveSameOriginPatchUrls(serverUrl, data.zstdPatch)
		: null;
	const chainUrls = data.patchChain
		? resolveSameOriginPatchChain(serverUrl, data.patchChain)
		: undefined;

	const releaseInfo: ReleaseInfo = {
		source: "update-server",
		version: data.version,
		releaseDate: data.releaseDate ?? new Date().toISOString(),
		releaseNotes: data.releaseNotes,
		path: data.file.filename,
		sha512: data.file.sha512,
		files: [
			{
				url: data.file.filename,
				size: data.file.size,
				sha512: data.file.sha512,
			},
		],
		_v2: {
			serverUrl,
			zstdPatchUrl: directPatchUrls?.url,
			zstdPatchMetaUrl: directPatchUrls?.metaUrl,
			patchChain: chainUrls,
		},
		releaseNotesPerVersion: data.releaseNotesPerVersion,
	};

	let downloadSize: number | undefined;
	let zstdPatchSize: number | undefined;
	let strategy: "zstd" | undefined;
	let patchChain: UpdateCheckResult["patchChain"];

	if (data.zstdPatch && directPatchUrls && data.zstdPatch.fromVersion === APP_VERSION) {
		zstdPatchSize = data.zstdPatch.patchSize;
		strategy = "zstd";
		downloadSize = zstdPatchSize;
	} else if (chainUrls && chainUrls.length > 0) {
		patchChain = chainUrls;
		strategy = "zstd";
		downloadSize = patchChain.reduce((sum, s) => sum + s.patchSize, 0);
	}

	const totalSize = data.file.size;
	if (!downloadSize) downloadSize = totalSize;

	return {
		updateAvailable: true,
		currentVersion: APP_VERSION,
		latestVersion: data.version,
		releaseInfo,
		downloadSize,
		totalSize,
		zstdPatchSize,
		strategy,
		patchChain,
	};
}
class ZstdCliMissingError extends Error {
	constructor() {
		super("zstd CLI required for patch-from mode");
		this.name = "ZstdCliMissingError";
	}
}
async function fetchPatchMeta(
	metaUrl: string,
	signal: AbortSignal | undefined,
	transport: UpdateFetchContext,
): Promise<ZstdPatchMeta> {
	const metaResp = await fetchWithTimeout(metaUrl, {
		timeoutMs: METADATA_FETCH_TIMEOUT_MS,
		signal,
		transport,
	});
	if (!metaResp.ok) {
		void metaResp.body?.cancel().catch(() => {});
		throw new Error(`Failed to fetch patch meta: ${metaResp.status}`);
	}
	return (await readUpdateJson(metaResp, 64 * 1024)) as ZstdPatchMeta;
}
async function downloadAndApplyPatchStep(context: PatchApplicationContext): Promise<void> {
	const patchTempPath = `${context.outputPath}.patch.${process.pid}.${Date.now()}.tmp`;
	const meta = context.meta;
	try {
		context.onProgress?.({
			phase: "downloading",
			bytesDownloaded: 0,
			totalBytes: meta.patchSize,
			percent: Math.round(context.progressBase),
		});

		const patchResp = await fetchWithTimeout(context.stepUrl, {
			timeoutMs: PAYLOAD_FETCH_TIMEOUT_MS,
			signal: context.signal,
			transport: context.transport,
		});
		if (!patchResp.ok) {
			void patchResp.body?.cancel().catch(() => {});
			throw new Error(`Failed to fetch patch: ${patchResp.status}`);
		}
		// Trust the smaller of the two announced sizes, with slack for header/framing drift.
		const declared = Math.max(meta.patchSize || 0, context.declaredPatchSize || 0);
		const maxPatchBytes = Math.min(
			MAX_PATCH_BYTES,
			declared > 0 ? Math.ceil(declared * PATCH_SIZE_SLACK) + 64 * 1024 : MAX_PATCH_BYTES,
		);
		const patchBytes = await streamResponseToFile(patchResp, patchTempPath, {
			maxBytes: maxPatchBytes,
			onProgress: (bytesWritten) => {
				context.onProgress?.({
					phase: "downloading",
					bytesDownloaded: bytesWritten,
					totalBytes: meta.patchSize,
					percent: Math.round(
						context.progressBase +
							context.progressSpan * 0.5 * Math.min(1, bytesWritten / (meta.patchSize || 1)),
					),
				});
			},
		});

		let zstdCliPath: string | undefined;
		if (meta.mode === "patch-from") {
			const cli = await getZstdCliPath(
				context.forceDownload,
				true,
				context.signal,
				context.helperContext,
			);
			if (!cli) throw new ZstdCliMissingError();
			zstdCliPath = cli;
		}

		logger.info("Applying zstd patch", {
			patchSize: patchBytes,
			newFileSize: meta.newFileSize,
			mode: meta.mode ?? "dictionary",
		});
		context.onProgress?.({
			phase: "applying",
			bytesDownloaded: patchBytes,
			totalBytes: meta.newFileSize,
			percent: Math.round(context.progressBase + context.progressSpan * 0.5),
		});

		await applyZstdPatchToFile({
			oldFilePath: context.sourcePath,
			patchFilePath: patchTempPath,
			outputFilePath: context.outputPath,
			meta,
			zstdPath: zstdCliPath,
			signal: context.signal,
			timeoutMs: PATCH_APPLY_TIMEOUT_MS,
			maxOutputBytes: MAX_BINARY_BYTES,
		});

		context.onProgress?.({
			phase: "applying",
			bytesDownloaded: patchBytes,
			totalBytes: meta.newFileSize,
			percent: Math.round(context.progressBase + context.progressSpan),
		});
	} finally {
		safeUnlink(patchTempPath);
	}
}
function assertPreparedUpdateCanBeReplaced(releaseInfo: ReleaseInfo): void {
	if (!isUpdateSourceCurrent(releaseInfo))
		throw new Error("Update source changed during download; check for updates again");
	if (getUpdateCoordinationStatus().scheduled)
		throw new Error(
			"A restart is already scheduled; keep its prepared update until it finishes or is cancelled",
		);
}
async function downloadUpdate(
	releaseInfo: ReleaseInfo,
	onProgress?: (progress: UpdateProgress) => void,
	options: { forceDownload?: boolean; signal?: AbortSignal } = {},
): Promise<{
	success: boolean;
	error?: string;
	version?: string;
	updatePath?: string;
	newBinaryPath?: string;
	placed?: boolean;
	preparedIdentity?: PreparedUpdateIdentity;
}> {
	const forceDownload = options.forceDownload ?? false;
	const sourceIdentity = parseUpdateSourceIdentity(releaseInfo.sourceIdentity);
	releaseInfo = { ...releaseInfo, sourceIdentity: sourceIdentity ?? undefined };
	const isGithub = releaseInfo.source === "github";
	if (!sourceIdentity || !isUpdateSourceCurrent(releaseInfo)) {
		return { success: false, error: "Update source changed; check for updates again" };
	}
	if (getUpdateCoordinationStatus().scheduled) {
		return {
			success: false,
			error:
				"A restart is already scheduled; keep its prepared update until it finishes or is cancelled",
		};
	}
	if (!isGithub && !getServerBaseUrl()) {
		return { success: false, error: "Update server not configured" };
	}

	const execPath = getCurrentExecutablePath();

	// Ensure update directory exists
	mkdirSync(UPDATE_DIR, { recursive: true });

	const releaseFileName = sanitizeUpdateFileName(releaseInfo.path, releaseInfo.version);
	const updatePath = join(UPDATE_DIR, releaseFileName);
	const tempPath = `${updatePath}.${process.pid}.${randomUUID()}.tmp`;
	let ownsGithubTemp = false;
	// Patch chains reconstruct one intermediate binary per step; both slots are reused.
	const intermediatePaths = [`${tempPath}.step-a`, `${tempPath}.step-b`];

	logger.info("Starting update download", {
		version: releaseInfo.version,
		execPath,
		hasV2: !!releaseInfo._v2,
	});

	const githubDeadline = isGithub ? createGithubUpdateDeadline(options.signal) : undefined;
	const signal = githubDeadline?.signal ?? options.signal;
	let githubStrategy: "full" | "zstd" = releaseInfo._github?.patchChain?.length ? "zstd" : "full";
	let githubFallback = false;
	let githubDownloadedBytes = 0;
	let githubDownloadTotal = releaseInfo.files[0]?.size ?? 0;
	const emitProgress = (progress: UpdateProgress) => {
		if (!isGithub) {
			onProgress?.(progress);
			return;
		}
		githubStrategy = progress.strategy ?? githubStrategy;
		githubFallback = progress.fallback ?? githubFallback;
		onProgress?.({ ...progress, strategy: githubStrategy, fallback: githubFallback });
	};
	try {
		signal?.throwIfAborted();
		const transport = createUpdateFetchContext();
		const helperContext = createDistributionContext(sourceIdentity, undefined, transport);
		emitProgress({
			phase: "downloading",
			bytesDownloaded: 0,
			totalBytes: releaseInfo.files[0]?.size ?? 0,
			percent: 0,
		});

		let applied = false;
		let zstdCliMissing = false;

		if (isGithub && githubDeadline) {
			const startedAt = Date.now();
			const strategy = await downloadGithubUpdateToFile(
				{
					release: releaseInfo,
					currentVersion: APP_VERSION,
					basePath: execPath,
					outputPath: tempPath,
					signal: githubDeadline.signal,
					onProgress: (progress) => {
						githubDownloadedBytes = progress.bytesDownloaded;
						githubDownloadTotal = progress.totalBytes;
						emitProgress(progress);
					},
				},
				{
					downloadPatch: (step, path, downloadOptions) =>
						downloadGithubPatchToFile(step, path, { ...downloadOptions, fetcher: transport.fetch }),
					downloadFull: (release, path, downloadOptions) =>
						downloadGithubBinaryToFile(release, path, {
							...downloadOptions,
							fetcher: transport.fetch,
						}),
					resolveZstd: (patchSignal) =>
						getZstdCliPath(forceDownload, true, patchSignal, helperContext),
					onFallback: (error) =>
						logger.warn("GitHub delta unavailable; downloading GitHub full binary", {
							source: "github",
							error: String(error),
						}),
				},
			);
			ownsGithubTemp = true;
			applied = true;
			logger.info("GitHub update downloaded", {
				source: "github",
				strategy,
				version: releaseInfo.version,
				bytes: releaseInfo.files[0]?.size,
				durationMs: Date.now() - startedAt,
			});
		}

		// Strategy: direct zstd patch (only the explicitly selected update server).
		if (!isGithub && execPath && existsSync(execPath)) {
			const zstdMetaUrl = releaseInfo._v2?.zstdPatchMetaUrl;
			const zstdPatchUrl = releaseInfo._v2?.zstdPatchUrl;

			if (zstdMetaUrl && zstdPatchUrl) {
				try {
					// Check the base version before spending a payload download on an unusable patch.
					const meta = await fetchPatchMeta(zstdMetaUrl, signal, transport);
					if (meta.fromVersion !== APP_VERSION) {
						logger.debug("Zstd patch version mismatch", {
							patchFrom: meta.fromVersion,
							current: APP_VERSION,
						});
					} else {
						await downloadAndApplyPatchStep({
							sourcePath: execPath,
							outputPath: tempPath,
							stepUrl: zstdPatchUrl,
							meta,
							declaredPatchSize: meta.patchSize,
							forceDownload,
							signal,
							transport,
							helperContext,
							onProgress,
							progressBase: 0,
							progressSpan: 100,
						});
						applied = true;
						logger.info("Zstd patch applied successfully", { resultSize: meta.newFileSize });
					}
				} catch (err) {
					if (err instanceof ZstdCliMissingError) zstdCliMissing = true;
					safeUnlink(tempPath);
					logger.warn("Zstd patch failed", { error: String(err) });
					if (signal?.aborted) throw err;
				}
			}
		}

		// Strategy: patch chain (multi-step)
		if (!isGithub && !applied && execPath && existsSync(execPath)) {
			const chain = releaseInfo._v2?.patchChain;
			if (chain && chain.length > 0) {
				try {
					logger.info("Using patch chain", { steps: chain.length });
					let sourcePath = execPath;

					for (let i = 0; i < chain.length; i++) {
						const step = chain[i];
						const isLast = i === chain.length - 1;
						const outputPath = isLast ? tempPath : intermediatePaths[i % 2];
						const meta = await fetchPatchMeta(step.metaUrl, signal, transport);
						await downloadAndApplyPatchStep({
							sourcePath,
							outputPath,
							stepUrl: step.url,
							meta,
							declaredPatchSize: step.patchSize,
							forceDownload,
							signal,
							transport,
							helperContext,
							onProgress,
							progressBase: (i / chain.length) * 100,
							progressSpan: (1 / chain.length) * 100,
						});
						// The previous intermediate is no longer needed once the next one exists.
						if (sourcePath !== execPath) safeUnlink(sourcePath);
						sourcePath = outputPath;
					}

					applied = true;
					logger.info("Patch chain applied successfully", { steps: chain.length });
				} catch (err) {
					if (err instanceof ZstdCliMissingError) zstdCliMissing = true;
					logger.warn("Patch chain failed", { error: String(err) });
					if (signal?.aborted) throw err;
				} finally {
					for (const path of intermediatePaths) safeUnlink(path);
				}
			}
		}

		if (!applied) {
			if (zstdCliMissing) {
				return {
					success: false,
					error: "ZSTD_CLI_MISSING",
				};
			}
			return {
				success: false,
				error:
					"No applicable update strategy: neither direct zstd patch nor patch chain available.",
			};
		}

		// Verify SHA512
		emitProgress({
			phase: "applying",
			bytesDownloaded: isGithub ? githubDownloadedBytes : (releaseInfo.files[0]?.size ?? 0),
			totalBytes: isGithub ? githubDownloadTotal : (releaseInfo.files[0]?.size ?? 0),
			percent: 100,
		});

		signal?.throwIfAborted();
		const actualSha512 = await computeFileSha512(tempPath, signal);
		signal?.throwIfAborted();
		if (actualSha512 !== releaseInfo.sha512) {
			unlinkSync(tempPath);
			return {
				success: false,
				error: `SHA512 mismatch: expected ${releaseInfo.sha512.slice(0, 16)}..., got ${actualSha512.slice(0, 16)}...`,
			};
		}

		let finalUpdatePath = updatePath;
		let newBinaryPath: string | undefined;
		let placed = false;
		let finalFileName = releaseFileName;

		if (execPath) {
			const destination = await resolvePreparedBinaryDestination(execPath, releaseInfo);
			signal?.throwIfAborted();
			assertPreparedUpdateCanBeReplaced(releaseInfo);
			newBinaryPath = destination.path;
			finalFileName = destination.fileName;
			if (destination.alreadyPresent) {
				unlinkSync(tempPath);
			} else {
				moveFileNoOverwriteSync(tempPath, newBinaryPath);
			}
			if (process.platform !== "win32") {
				chmodSync(newBinaryPath, 0o755);
			}
			finalUpdatePath = newBinaryPath;
			placed = true;
			logger.info("Update binary placed next to current executable", {
				newBinaryPath,
				version: releaseInfo.version,
				reusedExisting: destination.alreadyPresent,
			});
		} else {
			// Development mode fallback: keep the rebuilt binary in the update cache.
			const destination = await resolveUpdateCacheDestination(releaseInfo);
			signal?.throwIfAborted();
			assertPreparedUpdateCanBeReplaced(releaseInfo);
			finalUpdatePath = destination.path;
			finalFileName = destination.fileName;
			if (destination.alreadyPresent) {
				unlinkSync(tempPath);
			} else {
				moveFileNoOverwriteSync(tempPath, finalUpdatePath);
			}
		}

		const finalSize = statSync(finalUpdatePath).size;
		const preparedInfo: PlacedUpdateInfo = {
			sourceIdentity,
			version: releaseInfo.version,
			fromVersion: APP_VERSION,
			fileName: finalFileName,
			newBinaryPath,
			updatePath: finalUpdatePath,
			placed,
			placedAt: new Date().toISOString(),
			sha512: releaseInfo.sha512,
			sizeBytes: finalSize,
		};
		writePlacedUpdateInfo(preparedInfo);
		const preparedIdentity = preparedUpdateIdentity(preparedInfo);

		emitProgress({
			phase: "complete",
			bytesDownloaded: isGithub ? githubDownloadedBytes : (releaseInfo.files[0]?.size ?? 0),
			totalBytes: isGithub ? githubDownloadTotal : (releaseInfo.files[0]?.size ?? 0),
			percent: 100,
		});

		return {
			success: true,
			version: releaseInfo.version,
			updatePath: finalUpdatePath,
			newBinaryPath,
			placed,
			preparedIdentity,
		};
	} catch (err) {
		// The full-download helper owns cleanup on failure, including exclusive-create conflicts.
		if ((!isGithub || ownsGithubTemp) && existsSync(tempPath)) {
			try {
				unlinkSync(tempPath);
			} catch {}
		}

		const error = String(err);
		emitProgress({
			phase: "error",
			bytesDownloaded: 0,
			totalBytes: 0,
			percent: 0,
			error,
		});

		return { success: false, error };
	} finally {
		githubDeadline?.dispose();
	}
}
function moveFileNoOverwriteSync(src: string, dst: string): void {
	copyFileSync(src, dst, fsConstants.COPYFILE_EXCL);
	unlinkSync(src);
}
async function computeFileSha512(filePath: string, signal?: AbortSignal): Promise<string> {
	return new Promise((resolve, reject) => {
		const hash = createHash("sha512");
		const stream = createReadStream(filePath, { signal });

		stream.on("data", (chunk) => hash.update(chunk));
		stream.on("end", () => resolve(hash.digest("base64")));
		stream.on("error", reject);
	});
}

function formatProcessOutput(stdout: Uint8Array, stderr: Uint8Array): string {
	const decoder = new TextDecoder();
	const parts = [
		["stderr", decoder.decode(stderr).trim()],
		["stdout", decoder.decode(stdout).trim()],
	]
		.filter(([, value]) => value)
		.map(([label, value]) => `${label}: ${truncateForLog(value)}`);
	return parts.length > 0 ? parts.join("; ") : "no output";
}
function truncateForLog(value: string, maxLength = 4000): string {
	return value.length > maxLength ? `${value.slice(0, maxLength)}…` : value;
}
const MAX_CLI_OUTPUT_BYTES = 8 * 1024;
const DEFAULT_CLI_TIMEOUT_MS = 10 * 60_000;
async function applyZstdPatchToFile(
	options: ApplyZstdPatchToFileOptions,
): Promise<{ sizeBytes: number; sha512: string }> {
	const { meta, maxOutputBytes } = options;
	options.signal?.throwIfAborted();
	if (maxOutputBytes !== undefined && meta.newFileSize > maxOutputBytes) {
		throw new Error(
			`Zstd patch target size ${meta.newFileSize} exceeds the ${maxOutputBytes}-byte limit`,
		);
	}

	if (meta.mode === "patch-from") {
		await runZstdCliDecompress(options);
	} else {
		await applyLegacyDictionaryPatchToFile(options);
	}

	options.signal?.throwIfAborted();
	const stat = await Bun.file(options.outputFilePath).stat();
	options.signal?.throwIfAborted();
	if (stat.size !== meta.newFileSize) {
		throw new Error(
			`Zstd patch file size mismatch: expected ${meta.newFileSize}, got ${stat.size}`,
		);
	}
	const sha512 = await streamFileSha512(options.outputFilePath, options.signal);
	options.signal?.throwIfAborted();
	if (sha512 !== meta.newFileSha512) {
		throw new Error(
			`Zstd patch SHA512 mismatch: expected ${meta.newFileSha512.slice(0, 16)}..., got ${sha512.slice(0, 16)}...`,
		);
	}
	return { sizeBytes: stat.size, sha512 };
}
async function runZstdCliDecompress(options: ApplyZstdPatchToFileOptions): Promise<void> {
	const maximum = Math.min(
		options.meta.newFileSize,
		options.maxOutputBytes ?? options.meta.newFileSize,
	);
	if (!Number.isSafeInteger(maximum) || maximum < 0) throw new Error("Invalid zstd output ceiling");
	const timeoutMs = Math.max(1, options.timeoutMs ?? DEFAULT_CLI_TIMEOUT_MS);
	options.signal?.throwIfAborted();
	const deadline = AbortSignal.any([
		AbortSignal.timeout(timeoutMs),
		...(options.signal ? [options.signal] : []),
	]);
	const handle = await open(options.outputFilePath, "w");
	let proc: ReturnType<typeof Bun.spawn<"ignore", "pipe", "pipe">> | undefined;
	const onAbort = () => {
		proc?.kill("SIGKILL");
	};
	let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
	try {
		deadline.throwIfAborted();
		proc = Bun.spawn(
			[
				options.zstdPath ?? "zstd",
				"-d",
				`--patch-from=${options.oldFilePath}`,
				options.patchFilePath,
				"--stdout",
				"--long=31",
				"--memory=2048MB",
			],
			{
				stdin: "ignore",
				stdout: "pipe",
				stderr: "pipe",
				env: updateServerChildEnvironment(),
			},
		);
		deadline.addEventListener("abort", onAbort, { once: true });
		const stderr = readCappedStream(proc.stderr).catch(() => new Uint8Array());
		const outputReader = proc.stdout.getReader();
		reader = outputReader;
		let size = 0;
		while (true) {
			deadline.throwIfAborted();
			const chunk = await new Promise<{ done: boolean; value?: Uint8Array }>(
				(resolveChunk, reject) => {
					const onReadAbort = () => reject(deadline.reason);
					deadline.addEventListener("abort", onReadAbort, { once: true });
					outputReader
						.read()
						.then(resolveChunk, reject)
						.finally(() => deadline.removeEventListener("abort", onReadAbort));
				},
			);
			if (chunk.done) break;
			if (!chunk.value) throw new Error("zstd output stream produced no bytes");
			size += chunk.value.byteLength;
			if (size > maximum)
				throw new Error(`zstd CLI decompression output exceeds the ${maximum}-byte limit`);
			let offset = 0;
			while (offset < chunk.value.byteLength) {
				deadline.throwIfAborted();
				const { bytesWritten } = await handle.write(
					chunk.value,
					offset,
					chunk.value.byteLength - offset,
				);
				if (!bytesWritten) throw new Error("zstd output write made no progress");
				offset += bytesWritten;
			}
		}
		const [diagnostic, exitCode] = await Promise.all([stderr, proc.exited]);
		deadline.throwIfAborted();
		if (exitCode !== 0)
			throw new Error(
				`zstd CLI decompression failed (exit ${exitCode}): ${formatProcessOutput(new Uint8Array(), diagnostic)}`,
			);
	} catch (error) {
		proc?.kill("SIGKILL");
		if (deadline.aborted && !options.signal?.aborted)
			throw new Error(`zstd CLI decompression timed out after ${timeoutMs}ms`);
		throw error;
	} finally {
		deadline.removeEventListener("abort", onAbort);
		void reader?.cancel().catch(() => {});
		if (proc) await proc.exited;
		await handle.close();
	}
}
async function applyLegacyDictionaryPatchToFile(
	options: ApplyZstdPatchToFileOptions,
): Promise<void> {
	const { meta } = options;
	options.signal?.throwIfAborted();
	const oldBuf = await readFile(options.oldFilePath);
	if (meta.stableEnd > oldBuf.length) {
		throw new Error(
			`Old binary too small: expected at least ${meta.stableEnd} bytes, got ${oldBuf.length}`,
		);
	}
	const patch = await readFile(options.patchFilePath);
	options.signal?.throwIfAborted();

	const oldTail = oldBuf.subarray(meta.stableEnd);
	const restoredTail = await decompressZstd(
		patch,
		oldTail.length > 0 ? oldTail : undefined,
		meta.newTailSize,
	);
	if (restoredTail.length !== meta.newTailSize) {
		throw new Error(
			`Zstd patch tail size mismatch: expected ${meta.newTailSize}, got ${restoredTail.length}`,
		);
	}
	options.signal?.throwIfAborted();
	await writeFile(
		options.outputFilePath,
		Buffer.concat([oldBuf.subarray(0, meta.stableEnd), restoredTail]),
	);
}
function decompressZstd(
	patch: Buffer,
	dictionary?: Buffer,
	maxOutputLength?: number,
): Promise<Buffer> {
	return new Promise((resolveBuffer, reject) => {
		const done = (error: Error | null, result?: Buffer) => {
			if (error) reject(error);
			else resolveBuffer(result as Buffer);
		};
		// Bound the native allocation before decoding, not only after producing the buffer.
		const options = {
			...(dictionary ? { dictionary } : {}),
			...(maxOutputLength !== undefined ? { maxOutputLength: Math.max(1, maxOutputLength) } : {}),
		};
		zstdDecompress(patch, options, done);
	});
}
async function readCappedStream(
	stream: ReadableStream<Uint8Array> | number | undefined | null,
): Promise<Uint8Array> {
	if (!stream || typeof stream === "number") return new Uint8Array();
	const chunks: Uint8Array[] = [];
	let total = 0;
	const reader = stream.getReader();
	try {
		while (true) {
			const { done, value } = await reader.read();
			if (done) break;
			if (total >= MAX_CLI_OUTPUT_BYTES) continue;
			const slice = value.subarray(0, MAX_CLI_OUTPUT_BYTES - total);
			chunks.push(slice);
			total += slice.length;
		}
	} finally {
		reader.releaseLock();
	}
	const merged = new Uint8Array(total);
	let offset = 0;
	for (const chunk of chunks) {
		merged.set(chunk, offset);
		offset += chunk.length;
	}
	return merged;
}
async function streamFileSha512(filePath: string, signal?: AbortSignal): Promise<string> {
	signal?.throwIfAborted();
	const hash = createHash("sha512");
	// The decoder's caller owns the overall deadline; include this IO in that same signal.
	for await (const chunk of createReadStream(filePath, { signal })) {
		signal?.throwIfAborted();
		hash.update(chunk);
	}
	signal?.throwIfAborted();
	return hash.digest("base64");
}

async function fetchUpdateSameOrigin(
	url: string,
	init: RequestInit = {},
	context: UpdateFetchContext = createUpdateFetchContext(),
): Promise<Response> {
	const initial = new URL(url);
	if (!["http:", "https:"].includes(initial.protocol) || initial.username || initial.password)
		throw new Error("Invalid update request URL");
	let current = initial;
	for (let redirects = 0; redirects <= 5; redirects++) {
		init.signal?.throwIfAborted();
		const response = await context.fetch(current.toString(), { ...init, redirect: "manual" });
		if (response.redirected || (response.url && response.url !== current.toString())) {
			await response.body?.cancel().catch(() => {});
			throw new Error("Unexpected update request redirect");
		}
		if (![301, 302, 303, 307, 308].includes(response.status)) return response;
		await response.body?.cancel().catch(() => {});
		const location = response.headers.get("location");
		if (!location || redirects === 5) throw new Error("Update redirect limit reached");
		const next = new URL(location, current);
		if (next.origin !== initial.origin || next.username || next.password)
			throw new Error("Untrusted update request redirect");
		current = next;
	}
	throw new Error("Update redirect limit reached");
}
async function readUpdateJson(response: Response, maxBytes = 1024 * 1024): Promise<unknown> {
	const declared = response.headers.get("content-length");
	if (declared !== null && (!/^\d+$/.test(declared) || Number(declared) > maxBytes)) {
		void response.body?.cancel().catch(() => {});
		throw new Error("Update metadata exceeds size limit");
	}
	if (!response.body) throw new Error("Missing update metadata body");
	const reader = response.body.getReader();
	const decoder = new TextDecoder("utf-8", { fatal: true });
	let total = 0;
	let text = "";
	try {
		for (;;) {
			const { done, value } = await reader.read();
			if (done) break;
			total += value.byteLength;
			if (total > maxBytes) throw new Error("Update metadata exceeds size limit");
			text += decoder.decode(value, { stream: true });
		}
		text += decoder.decode();
		return JSON.parse(text);
	} finally {
		void reader.cancel().catch(() => {});
		reader.releaseLock();
	}
}
function waitForUpdate<T>(value: Promise<T>, signal: AbortSignal): Promise<T> {
	signal.throwIfAborted();
	return new Promise((resolve, reject) => {
		const abort = () => reject(signal.reason ?? new DOMException("Update cancelled", "AbortError"));
		signal.addEventListener("abort", abort, { once: true });
		value.then(resolve, reject).finally(() => signal.removeEventListener("abort", abort));
	});
}
async function fetchUpdateWithTimeout(
	url: string,
	options: { timeoutMs: number; signal?: AbortSignal; transport?: UpdateFetchContext },
): Promise<Response> {
	options.signal?.throwIfAborted();
	const controller = new AbortController();
	const signal = options.signal
		? AbortSignal.any([options.signal, controller.signal])
		: controller.signal;
	const timeout = setTimeout(
		() => controller.abort(new DOMException("Update request timed out", "TimeoutError")),
		options.timeoutMs,
	);
	let disposed = false;
	const dispose = () => {
		if (!disposed) {
			disposed = true;
			clearTimeout(timeout);
		}
	};
	try {
		const pending = fetchUpdateSameOrigin(url, { signal }, options.transport);
		void pending.then(
			(response) => {
				if (signal.aborted) void response.body?.cancel().catch(() => {});
			},
			() => {},
		);
		const response = await waitForUpdate(pending, signal);
		if (!response.body) {
			dispose();
			return response;
		}
		const reader = response.body.getReader();
		let bodyController: ReadableStreamDefaultController<Uint8Array>;
		const abort = () => {
			dispose();
			void reader.cancel().catch(() => {});
			bodyController.error(signal.reason ?? new DOMException("Update cancelled", "AbortError"));
		};
		const finish = () => {
			dispose();
			signal.removeEventListener("abort", abort);
		};
		const body = new ReadableStream<Uint8Array>(
			{
				start(stream) {
					bodyController = stream;
					signal.addEventListener("abort", abort, { once: true });
					if (signal.aborted) abort();
				},
				async pull(stream) {
					try {
						const next = await waitForUpdate(reader.read(), signal);
						if (next.done) {
							finish();
							stream.close();
						} else stream.enqueue(next.value);
					} catch (error) {
						finish();
						stream.error(error);
						void reader.cancel().catch(() => {});
					}
				},
				cancel(reason) {
					finish();
					void reader.cancel(reason).catch(() => {});
				},
			},
			{ highWaterMark: 0 },
		);
		return new Response(body, {
			status: response.status,
			statusText: response.statusText,
			headers: response.headers,
		});
	} catch (error) {
		dispose();
		throw error;
	}
}
